css:
.stage {
  padding: 32px;
  font-family: system-ui, sans-serif;
}

.card {
  max-width: 320px;
  padding: 20px;
  border: 3px solid transparent;
  border-radius: 16px;
  background-image: linear-gradient(#ffffff, #ffffff), linear-gradient(135deg, #f97316, #ec4899);
  background-origin: border-box;
  background-clip: padding-box, border-box;
}

.card-title {
  margin: 0 0 6px;
}

.card-text {
  margin: 0;
  color: #52525b;
}
